test -f supabase/migrations/0198_line_oa_revoke_client_write_grants.sql
# No anon/authenticated/service_role table or column write privilege may remain.
psql "postgresql://postgres@127.0.0.1:55447/postgres" -tAc "select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join unnest(array['anon','authenticated','service_role']) r(role) where n.nspname='public' and c.relkind='r' and c.relname in ('line_oa_channels','line_oa_conversations','line_oa_inbound_messages','line_oa_outbound_messages','line_oa_customer_identity','line_oa_message_templates','line_oa_orders','line_oa_audit_log') and (has_table_privilege(r.role,c.oid,'INSERT') or has_table_privilege(r.role,c.oid,'UPDATE') or has_table_privilege(r.role,c.oid,'DELETE') or has_table_privilege(r.role,c.oid,'TRUNCATE') or has_any_column_privilege(r.role,c.oid,'INSERT') or has_any_column_privilege(r.role,c.oid,'UPDATE'))" | grep -qx 0
